import React, { useEffect, useState } from 'react';
import { useStore } from '../../../../Context/StoreContext';
import axios from '../../../../Utils/axios';
import { MdSave } from 'react-icons/md';

const UpdateProfile = () => {
  const { setNotification, getUserData, userData } = useStore();
  const [data, setData] = useState({ name: '', gender: '', birthday: '' });

  useEffect(() => {
    setData(userData);
  }, [userData]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios().patch('/auth/profile/update-profile', data);

      console.log(res.data);

      setNotification({
        type: 'success',
        message: res.data.msg,
      });

      getUserData();
    } catch (err) {
      console.log(err);
      setNotification({
        type: 'error',
        message: err.response.data ? err.response.data.msg : err.message,
      });
    }
  };

  return (
    <>
      <form className=" d-flex flex-column" onSubmit={handleSubmit}>
        <label className="form-label mt-2" htmlFor="name">
          Enter your Name
        </label>
        <input
          type="text"
          name="name"
          className="form-control  w-100"
          autoComplete="off"
          id="name"
          value={data.name}
          onChange={(e) => setData({ ...data, name: e.target.value })}
        />
        <label className="form-label mt-2" htmlFor="gender">
          Enter Gender
        </label>
        <input
          type="text"
          name="gender"
          autoComplete="off"
          className="form-control  w-100"
          id="gender"
          value={data.gender}
          onChange={(e) => setData({ ...data, gender: e.target.value })}
        />
        <label className="form-label mt-2" htmlFor="birthday">
          Enter DOB
        </label>
        <input
          type="date"
          name="birthday"
          autoComplete="off"
          className="form-control  w-100"
          id="birthday"
          value={data.birthday}
          onChange={(e) => setData({ ...data, birthday: e.target.value })}
        />

        <button type="submit" className="btn btn-success w-100 mt-2">
          <MdSave className="me-1" />
          Update Profile
        </button>
      </form>
    </>
  );
};

export default UpdateProfile;
