import React, { useState } from 'react';
import axios from '../../../../Utils/axios';
import { useStore } from '../../../../Context/StoreContext';
import { MdSave, MdDeleteForever } from 'react-icons/md';

const UpdateProfileImage = () => {
  const [imageFile, setImageFile] = useState(null);
  const { setNotification, getUserData, getCommentsData } = useStore();

  const handleSubmit = async (e, action) => {
    e.preventDefault();

    let imageData = new FormData();

    if (action === 'delete') {
      imageData.append('profile_image', null);
    } else {
      if (!imageFile) {
        setNotification({
          type: 'error',
          message: 'Please provide Image',
        });
        return;
      }

      imageData.append('profile_image', imageFile);
    }

    try {
      const res = await axios().patch(
        '/auth/profile/update-profile-image',
        imageData,
        {
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        }
      );

      console.log(res.data);

      setNotification({
        type: 'success',
        message: res.data.msg,
      });

      getUserData();
      getCommentsData();
    } catch (err) {
      console.log(err);
      setNotification({
        type: 'error',
        message: err.response.data ? err.response.data.msg : err.message,
      });
    }
  };

  return (
    <>
      <form className=" d-flex flex-column">
        <label className="form-label mt-2" htmlFor="image">
          Select Profile Picture
        </label>
        <input
          type="file"
          id="image"
          accept="image/png, image/jpg, image/jpeg"
          className="form-control  w-100"
          onChange={(e) => {
            setImageFile(e.target.files[0]);
          }}
        />

        {/* <button type="submit" className="btn btn-success w-100 mt-2">
          Update Profile
        </button> */}

        <div className="d-flex flex-row flex-wrap gap-2 mt-2">
          <button
            type="button"
            className="btn btn-success flex-fill"
            onClick={(e) => handleSubmit(e, 'update')}
          >
            <MdSave className="me-1" />
            Upload Profile Picture
          </button>
          <button
            type="button"
            className="btn btn-danger flex-fill"
            onClick={(e) => handleSubmit(e, 'delete')}
          >
            <MdDeleteForever className="me-1" />
            Remove Profile Picture
          </button>
        </div>
      </form>
    </>
  );
};

export default UpdateProfileImage;
