import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from '../../../Utils/axios';
import { useStore } from '../../../Context/StoreContext';
import { MdHome, MdAccountBox } from 'react-icons/md';

const initialState = {
  name: '',
  email: '',
  password: '',
  confirmPassword: '',
};

const SignUp = () => {
  const { setNotification } = useStore();
  const navigate = useNavigate();
  const [userDetail, setUserDetail] = useState(initialState);
  const [showPassword, setShowPassword] = useState(false);

  const handleChage = (e) => {
    const { name, value } = e.target;

    setUserDetail({
      ...userDetail,
      [name]: value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const { password, confirmPassword } = userDetail;

    if (!password || !confirmPassword) {
      setNotification({
        type: 'error',
        message: 'Please provide password and confirm password',
      });
      return;
    }

    if (password !== confirmPassword) {
      setNotification({
        type: 'error',
        message: "Password did't match",
      });
      return;
    }

    try {
      const res = await axios().post('/auth/register', userDetail);

      console.log(res);

      setNotification({
        type: 'success',
        message: res.data.msg,
      });

      if (res.data) {
        navigate('/');
      }
    } catch (err) {
      console.log(err);
      setNotification({
        type: 'error',
        message: err.response.data ? err.response.data.msg : err.message,
      });
    }
  };

  return (
    <>
      <div className="d-flex justify-content-between my-2">
        <button className="btn btn-light" onClick={() => navigate('/')}>
          <MdHome className="me-1" />
          Home
        </button>
      </div>
      <form className="d-flex flex-column" onSubmit={handleSubmit}>
        <label className="form-label mt-2" htmlFor="name">
          Name
        </label>
        <input
          name="name"
          id="name"
          autoComplete="off"
          className="form-control"
          type="text"
          value={userDetail.name}
          onChange={handleChage}
        />

        <label className="form-label mt-2" htmlFor="email">
          Email
        </label>
        <input
          name="email"
          className="form-control"
          id="email"
          autoComplete="off"
          value={userDetail.email}
          onChange={handleChage}
        />
        <label className="form-label mt-2" htmlFor="password">
          Password
        </label>

        <div className="input-group ">
          <input
            name="password"
            id="password"
            className="form-control"
            // autoComplete="off"
            autoComplete="new-password"
            type={showPassword ? 'text' : 'password'}
            value={userDetail.password}
            onChange={handleChage}
          />
          <span
            className="input-group-text"
            onClick={() => {
              setShowPassword((current) => !current);
            }}
          >
            {showPassword === true ? 'Hide' : 'Show'}
          </span>
        </div>

        <label className="form-label mt-2" htmlFor="confirmPassword">
          Confirm Password
        </label>

        <div className="input-group ">
          <input
            name="confirmPassword"
            id="confirmPassword"
            className="form-control"
            autoComplete="off"
            type={showPassword ? 'text' : 'password'}
            value={userDetail.confirmPassword}
            onChange={handleChage}
          />
          <span
            className="input-group-text"
            onClick={() => {
              setShowPassword((current) => !current);
            }}
          >
            {showPassword === true ? 'Hide' : 'Show'}
          </span>
        </div>

        <button type="submit" className="btn btn-primary w-100 mt-2">
          <MdAccountBox className="me-1" />
          Register
        </button>
      </form>

      <div className="my-2 text-center">
        <Link to="/">Already Register?</Link>
      </div>
    </>
  );
};

export default SignUp;
