import React, { useContext, useState, useEffect } from 'react';
import axios from '../Utils/axios';

const storeContext = React.createContext();

export function useStore() {
  return useContext(storeContext);
}

export function StoreProvider({ children }) {
  const [userData, setUserData] = useState({});
  const [websiteId, setWebsiteId] = useState(null);

  const [showNotification, setShowNotification] = useState(false);
  const [notification, setNotification] = useState({
    type: '',
    message: '',
  });

  const [commentsData, setCommentsData] = useState([]);

  useEffect(() => {
    const id = document.getElementById('gimme-comments-root').dataset
      .gimme_comments_website_id;

    setWebsiteId(id ? id : '64b0305d9d7307301d5b8dxx');
  }, []);

  useEffect(() => {
    if (notification.message === '') return;

    setShowNotification(true);
    setTimeout(() => setShowNotification(false), 3000);
  }, [notification]);

  const getCommentsData = async () => {
    try {
      if (!websiteId) return;

      const res = await axios().get(`/comments/comment/${websiteId}`);

      console.log(res.data.comments);

      setCommentsData(res.data.comments);
    } catch (err) {
      console.log(err);
      setNotification({
        type: 'error',
        message: err.response.data ? err.response.data.msg : err.message,
      });
    }
  };

  const getUserData = async () => {
    try {
      const res = await axios().get('/auth/profile/');

      console.log(res.data.user);

      setUserData(res.data.user);
    } catch (err) {
      console.log(err);
      setNotification({
        type: 'error',
        message: err.response.data ? err.response.data.msg : err.message,
      });
    }
  };

  return (
    <storeContext.Provider
      value={{
        websiteId,
        notification,
        setNotification,
        showNotification,
        userData,
        getUserData,
        commentsData,
        getCommentsData,
      }}
    >
      {children}
    </storeContext.Provider>
  );
}
