import React, { useEffect, useState } from 'react';

import Router from './Router/Router';
import Notification from './Components/Notification';
import 'bootstrap/dist/css/bootstrap.css';
import AllComments from './Pages/Comments/AllComments/AllComments';
import { useStore } from './Context/StoreContext';
import axios from './Utils/axios';

const App = () => {
  const { websiteId } = useStore();

  const [websiteData, setWebsiteData] = useState({});

  useEffect(() => {
    const getWebsiteData = async () => {
      console.log('websitedata', websiteId);
      if (!websiteId) return;
      try {
        const res = await axios().get(`/websites/exists/${websiteId}`);

        console.log(res.data);

        setWebsiteData(res.data);
      } catch (err) {
        console.log(err);
        setWebsiteData(null);
      }
    };

    getWebsiteData();
  }, [websiteId]);

  if (!websiteData) {
    return (
      <>
        <svg xmlns="http://www.w3.org/2000/svg" style={{ display: 'none' }}>
          <symbol id="exclamation-triangle-fill" viewBox="0 0 16 16">
            <path d="M8.982 1.566a1.13 1.13 0 0 0-1.96 0L.165 13.233c-.457.778.091 1.767.98 1.767h13.713c.889 0 1.438-.99.98-1.767L8.982 1.566zM8 5c.535 0 .954.462.9.995l-.35 3.507a.552.552 0 0 1-1.1 0L7.1 5.995A.905.905 0 0 1 8 5zm.002 6a1 1 0 1 1 0 2 1 1 0 0 1 0-2z" />
          </symbol>
        </svg>
        <div
          className="alert alert-danger mb-0 d-flex align-items-center justify-content-center p-2"
          role="alert"
        >
          <svg
            className="bi flex-shrink-0 me-2"
            style={{ height: '20px', width: '20px' }}
            role="img"
            aria-label="Danger:"
          >
            <use xlinkHref="#exclamation-triangle-fill" />
          </svg>
          <div>Gimme Comments is not activated for this website</div>
        </div>
      </>
    );
  }

  return (
    <>
      <div className="d-flex flex-column gap-2 my-2">
        <Router />
        <Notification />
        <AllComments />
      </div>
    </>
  );
};

export default App;
