import React, { useState } from 'react';
import { useStore } from '../../../../Context/StoreContext';
import axios from '../../../../Utils/axios';

import { MdSave } from 'react-icons/md';
const UpdatePassword = () => {
  const { setNotification, getUserData } = useStore();
  const [data, setData] = useState({ old_password: '', new_password: '' });

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios().patch('/auth/profile/update-password', data);

      console.log(res.data);

      setNotification({
        type: 'success',
        message: res.data.msg,
      });

      getUserData();
    } catch (err) {
      console.log(err);
      setNotification({
        type: 'error',
        message: err.response.data ? err.response.data.msg : err.message,
      });
    }
  };

  return (
    <>
      <form className=" d-flex flex-column" onSubmit={handleSubmit}>
        <label className="form-label mt-2" htmlFor="old_password">
          Enter Old Password
        </label>
        <input
          type="password"
          name="old_password"
          className="form-control  w-100"
          autoComplete="off"
          id="old_password"
          value={data.old_password}
          onChange={(e) => setData({ ...data, old_password: e.target.value })}
        />
        <label className="form-label mt-2" htmlFor="new_password">
          Enter New Password
        </label>
        <input
          type="password"
          name="new_password"
          className="form-control  w-100"
          autoComplete="off"
          id="new_password"
          value={data.new_password}
          onChange={(e) => setData({ ...data, new_password: e.target.value })}
        />

        <button type="submit" className="btn btn-success w-100 mt-2">
          <MdSave className="me-1" />
          Update Password
        </button>
      </form>
    </>
  );
};

export default UpdatePassword;
