import axios from '../../../Utils/axios';
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useStore } from '../../../Context/StoreContext';
import { MdHome } from 'react-icons/md';

const VerifyAccount = () => {
  const navigate = useNavigate();
  const { setNotification } = useStore();
  const [page, setPage] = useState(1);
  const [data, setData] = useState({
    email: '',
    otp: 0,
  });

  const handleSubmit = (e) => {
    e.preventDefault();

    if (page === 1) {
      generateOTP();
    } else {
      verifyOTP();
    }
  };

  const generateOTP = async () => {
    try {
      const res = await axios().post(
        '/auth/account-verification/generate-otp',
        { email: data.email }
      );

      console.log(res.data);

      setNotification({
        type: 'success',
        message: res.data.msg,
      });

      setPage(2);
    } catch (err) {
      console.log(err);
      setNotification({
        type: 'error',
        message: err.response.data ? err.response.data.msg : err.message,
      });
    }
  };

  const verifyOTP = async () => {
    try {
      const res = await axios().post(
        '/auth/account-verification/verify-account',
        { email: data.email, otp: Number(data.otp) }
      );

      console.log(res.data);

      setNotification({
        type: 'success',
        message: res.data.msg,
      });

      navigate('/');
    } catch (err) {
      console.log(err);
      setNotification({
        type: 'error',
        message: err.response.data ? err.response.data.msg : err.message,
      });
    }
  };

  return (
    <>
      <div className="d-flex justify-content-between my-2">
        <button className="btn btn-light" onClick={() => navigate('/')}>
          <MdHome className="me-1" />
          Home
        </button>
      </div>
      <form onSubmit={handleSubmit}>
        <label className="form-label mt-2" htmlFor="email">
          Enter your Email{' '}
        </label>
        <input
          name="email"
          id="email"
          autoComplete="off"
          className="form-control"
          type="email"
          value={data.email}
          disabled={!(page === 1)} // It will disabled editing
          onChange={(e) => setData({ ...data, email: e.target.value })}
        />

        {page !== 1 && (
          <>
            <label className="form-label mt-2" htmlFor="otp">
              Enter OTP
            </label>
            <div className="input-group ">
              <input
                name="otp"
                id="otp"
                autoComplete="off"
                type="number"
                className="form-control"
                value={data.otp}
                onChange={(e) =>
                  setData({ ...data, otp: Number(e.target.value) })
                }
              />
              <span
                className="input-group-text btn btn-info"
                onClick={() => generateOTP()}
              >
                Get OTP again
              </span>
            </div>
          </>
        )}

        <button type="submit" className="btn btn-success w-100 mt-2">
          {page === 1 && 'Get OTP'}
          {page === 2 && 'Verify Account'}
        </button>
      </form>
    </>
  );
};

export default VerifyAccount;
