import React from 'react';
import { useNavigate, Outlet } from 'react-router-dom';
import { useStore } from '../../../Context/StoreContext';
// {{BASE_URL}}/api/v1/auth/profile/
import { MdHome, MdLogout } from 'react-icons/md';

const default_profile_image =
  'https://ncshah.com/wp-content/uploads/2022/05/default_profile_img.jpg';

const Profile = () => {
  const navigate = useNavigate();
  const { userData, setNotification } = useStore();

  const Logout = () => {
    setNotification({
      type: 'success',
      message: 'Logged Out Successfully',
    });

    setTimeout(() => {
      localStorage.removeItem('gimme_comment_access_token');
      window.location.reload();
    }, 1000);
  };

  return (
    <>
      <div className="d-flex justify-content-between my-2">
        <button className="btn btn-light" onClick={() => navigate('/comment')}>
          <MdHome className="me-1" />
          Home
        </button>
        <button className="btn btn-outline-danger" onClick={Logout}>
          <MdLogout className="me-1" />
          Log out
        </button>
      </div>

      <div className="d-flex justify-content-center align-items-center my-3">
        <img
          className="rounded-circle shadow-lg"
          src={userData.profile_image || default_profile_image}
          alt="profile"
          style={{
            width: '100px',
            height: '100px',
            objectFit: 'cover',
          }}
        />
        <div className="ms-3">
          <strong>{userData.name}</strong>

          <div>{userData.email}</div>
        </div>
      </div>

      <div className="d-flex flex-row flex-wrap my-3">
        <button
          className="btn btn-outline-secondary border-0 border-bottom rounded-0 flex-fill"
          onClick={() => navigate('update-profile')}
        >
          Update Profile
        </button>
        <button
          className="btn btn-outline-secondary border-0 border-bottom rounded-0 flex-fill"
          onClick={() => navigate('update-password')}
        >
          Update Password
        </button>
        <button
          className="btn btn-outline-secondary border-0 border-bottom rounded-0 flex-fill"
          onClick={() => navigate('update-profile-image')}
        >
          Update Profile Image
        </button>
      </div>
      <Outlet />
    </>
  );
};

export default Profile;
