import React, { useState, useEffect } from 'react';
import { useStore } from '../../../Context/StoreContext';
import SingleComment from './SingleComment';

const AllComments = () => {
  const { commentsData, getCommentsData, websiteId } = useStore();
  const [nestedCommentsData, setNestedCommentsDat] = useState([]);

  useEffect(() => {
    const buildTree = (comment_parent) => (item) => {
      const nested_comments = commentsData.filter(
        (child) => child.comment_parent === item._id
      );
      return {
        ...item,
        ...(nested_comments.length > 0 && {
          nested_comments: nested_comments.map(buildTree(item._id)),
        }),
      };
    };

    const nestedData = commentsData
      .filter((item) => !item.comment_parent)
      .map(buildTree(undefined));

    setNestedCommentsDat(nestedData);
  }, [commentsData]);

  useEffect(() => {
    if (!websiteId) return;

    getCommentsData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [websiteId]);

  console.log(nestedCommentsData);

  useEffect(() => {});

  return (
    <>
      <div className="border border-1 rounded-4 p-1 overflow-auto">
        {nestedCommentsData.length === 0 ? (
          <>
            <span>Be the First to Comment...</span>
          </>
        ) : (
          nestedCommentsData.map((comment) => {
            return <SingleComment key={comment._id} commentData={comment} />;
          })
        )}
      </div>
    </>
  );
};

export default AllComments;
