import React, { useEffect, useState } from 'react';
// import axios from '../../../Utils/axios';
import ReactMarkdown from 'react-markdown';
import { useStore } from '../../../Context/StoreContext';
import axios from '../../../Utils/axios';

import CreateComment from '../CreateComment/CreateComment';

import {
  MdDeleteForever,
  MdSave,
  MdThumbUp,
  MdReply,
  MdEdit,
} from 'react-icons/md';
import { VscOpenPreview } from 'react-icons/vsc';

const default_profile_image =
  'https://ncshah.com/wp-content/uploads/2022/05/default_profile_img.jpg';

const SingleComment = ({ commentData }) => {
  const { userData, getCommentsData, setNotification } = useStore();

  const [inEditMode, setInEditMode] = useState(false);
  const [inReplyMode, setInReplyMode] = useState(false);
  const [showMarkdownPreview, setShowMarkdownPreview] = useState(false);

  const [userComment, setUserComment] = useState({
    comment_description: '',
  });

  useEffect(() => {
    setUserComment({
      comment_description: commentData.comment_description,
    });
  }, [commentData]);

  // handle update comment
  const handleUpdateComment = async (e) => {
    e.preventDefault();
    try {
      const res = await axios().patch(
        `/comments/comment/${commentData._id}`,
        userComment
      );

      console.log(res.data.comment);

      setNotification({
        type: 'success',
        message: 'Comment updated successfully',
      });

      setInEditMode(false);
      getCommentsData();
    } catch (err) {
      console.log(err);
      setNotification({
        type: 'error',
        message: err.response.data ? err.response.data.msg : err.message,
      });
    }
  };

  const handleLikeUnlikeComment = async () => {
    if (!userData._id) {
      setNotification({
        type: 'warning',
        message: 'Login First',
      });
      return;
    }
    try {
      if (!commentData.i_liked) {
        const res = await axios().post(`/comments/like/${commentData._id}`);

        console.log(res.data.comment);

        setNotification({
          type: 'success',
          message: 'Comment like added',
        });
      } else {
        const res = await axios().delete(`/comments/like/${commentData._id}`);

        console.log(res.data.comment);

        setNotification({
          type: 'success',
          message: 'Comment like removed',
        });
      }

      getCommentsData();
    } catch (err) {
      console.log(err);
      setNotification({
        type: 'error',
        message: err.response.data ? err.response.data.msg : err.message,
      });
    }
  };

  // handle delete comment
  const handleDeleteComment = async (e) => {
    e.preventDefault();
    try {
      const res = await axios().delete(`/comments/comment/${commentData._id}`);

      console.log(res.data.comment);

      setNotification({
        type: 'success',
        message: 'Comment deleted successfully',
      });

      setInEditMode(false);

      setTimeout(() => {
        getCommentsData();
      }, 500);
    } catch (err) {
      console.log(err);
      setNotification({
        type: 'error',
        message: err.response.data ? err.response.data.msg : err.message,
      });
    }
  };

  return (
    <div className="d-flex align-items-stretch gap-2 flex-row flex-nowrap  mt-2">
      <div
        style={{
          position: 'relative',
        }}
      >
        <img
          className="rounded-circle"
          src={commentData.by_user.profile_image || default_profile_image}
          alt="profile"
          style={{
            width: '40px',
            height: '40px',
            objectFit: 'cover',
          }}
        />
        <div
          style={{
            position: 'absolute',
            height: 'calc(100% - 40px)',
            width: '100%',
            borderLeft: '2px grey solid',
            transform: 'translateX(50%)',
          }}
        />
      </div>
      <div className="flex-fill">
        <div className="bg-light p-2 rounded-4 shadow-sm">
          <div className="mb-2">
            <strong>{commentData.by_user.name}</strong>
            {' - '}
            <span className="text-body-secondary" style={{ fontSize: '80%' }}>
              {commentData.by_user.email +
                ' | ' +
                new Date(commentData.createdAt).toLocaleString()}
            </span>
          </div>
          <div
            className={`${
              inEditMode ? 'd-flex flex-wrap' : 'p-2'
            } rounded-4 overflow-hidden`}
          >
            {inEditMode ? (
              <>
                <textarea
                  type="text"
                  name="comment_description"
                  className={`${
                    showMarkdownPreview ? 'w-50' : 'w-100'
                  } rounded-0 border-0 form-control`}
                  placeholder="Add a comment..."
                  value={userComment.comment_description}
                  onChange={(e) =>
                    setUserComment({ comment_description: e.target.value })
                  }
                />

                {showMarkdownPreview && (
                  <div className="w-50 py-1 px-3 border border-primary border-2 rounded-end-4 overflow-auto">
                    <ReactMarkdown>
                      {userComment.comment_description ||
                        '**Styling with [Markdown](https://www.markdownguide.org/basic-syntax/)**'}
                    </ReactMarkdown>
                  </div>
                )}
              </>
            ) : (
              <>
                <ReactMarkdown>{commentData.comment_description}</ReactMarkdown>
              </>
            )}
          </div>

          {inEditMode && (
            <>
              <div className="d-flex align-items-center mt-2">
                <button
                  className="btn btn-danger"
                  onClick={handleDeleteComment}
                >
                  <MdDeleteForever />
                </button>
                <button
                  className="btn btn-outline-primary ms-auto me-2"
                  onClick={() => setShowMarkdownPreview(!showMarkdownPreview)}
                >
                  <VscOpenPreview /> Preview
                </button>
                <button
                  className="btn btn-success"
                  onClick={handleUpdateComment}
                >
                  <MdSave />
                </button>
              </div>
            </>
          )}
        </div>
        <div className="d-flex gap-2 px-2">
          <button
            className="btn btn-link text-body-secondary p-1"
            onClick={() => handleLikeUnlikeComment()}
          >
            <MdThumbUp /> {commentData.liked_by + ' '}
            {commentData.i_liked ? 'Unlike' : 'Like'}
          </button>
          <button
            className="btn btn-link text-body-secondary p-1"
            onClick={() => {
              if (!userData._id) {
                setNotification({
                  type: 'warning',
                  message: 'Login First',
                });
                return;
              }
              setInReplyMode(!inReplyMode);
            }}
          >
            <MdReply /> {!inReplyMode ? 'Reply' : 'Cancel'}
          </button>
          {userData._id === commentData.by_user._id && (
            <>
              <button
                className="btn btn-link text-body-secondary p-1 ms-auto"
                onClick={() => setInEditMode(!inEditMode)}
              >
                <MdEdit />
                {!inEditMode ? 'Edit' : 'Cancel'}
              </button>
            </>
          )}
        </div>
        {inReplyMode && (
          <CreateComment
            commentParentId={commentData._id}
            setInReplyMode={setInReplyMode}
          />
        )}
        {commentData.nested_comments?.map((comment) => {
          return <SingleComment key={comment._id} commentData={comment} />;
        })}
      </div>
    </div>
  );
};

export default SingleComment;
