import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from '../../../Utils/axios';
import { useStore } from '../../../Context/StoreContext';
import ReactMarkdown from 'react-markdown';

import { MdSend } from 'react-icons/md';
import { VscOpenPreview } from 'react-icons/vsc';
import GimmeCommentsLogo from '../../../assets/GimmeCommentsLogo.png';

const default_profile_image =
  'https://ncshah.com/wp-content/uploads/2022/05/default_profile_img.jpg';

const CreateComment = ({ commentParentId, setInReplyMode }) => {
  const navigate = useNavigate();
  const { setNotification, userData, websiteId, getCommentsData } = useStore();
  const [showMarkdownPreview, setShowMarkdownPreview] = useState(false);

  const [userComment, setUserComment] = useState({
    comment_description: '',
    comment_parent: commentParentId,
  });

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      console.log(userComment);
      const res = await axios().post(
        `/comments/comment/${websiteId}`,
        userComment
      );

      console.log(res.data.comment);

      setNotification({
        type: 'success',
        message: 'Comment created successfully',
      });

      if (commentParentId) setInReplyMode(false);

      getCommentsData();
    } catch (err) {
      console.log(err);
      setNotification({
        type: 'error',
        message: err.response.data ? err.response.data.msg : err.message,
      });
    }
  };

  return (
    <>
      <div className="d-flex gap-2 flex-row flex-nowrap align-items-start">
        {!commentParentId ? (
          <>
            <button
              className="btn btn-light rounded-circle p-1 shadow"
              onClick={() => navigate('/profile/update-profile')}
            >
              <img
                className="rounded-circle"
                src={userData.profile_image || default_profile_image}
                alt="profile"
                style={{
                  width: '40px',
                  height: '40px',
                  objectFit: 'cover',
                }}
              />
            </button>
          </>
        ) : (
          <>
            <img
              className="rounded-circle"
              src={userData.profile_image || default_profile_image}
              alt="profile"
              style={{
                width: '40px',
                height: '40px',
                objectFit: 'cover',
              }}
            />
          </>
        )}
        <div className="flex-fill bg-light p-2 rounded-4 shadow-sm">
          <div className="d-flex flex-wrap rounded-4 overflow-hidden">
            <textarea
              type="text"
              name="comment_description"
              className={`${
                showMarkdownPreview ? 'w-50' : 'w-100'
              } rounded-0 border-0 form-control`}
              placeholder={`${
                commentParentId ? 'Reply to' : 'Add'
              } a comment...`}
              value={userComment.comment_description}
              onChange={(e) =>
                setUserComment({
                  ...userComment,
                  comment_description: e.target.value,
                })
              }
            />

            {showMarkdownPreview && (
              <div className="w-50 py-1 px-3 border border-primary border-2 rounded-end-4 overflow-auto">
                <ReactMarkdown>
                  {userComment.comment_description ||
                    '**Styling with [Markdown](https://www.markdownguide.org/basic-syntax/)**'}
                </ReactMarkdown>
              </div>
            )}
          </div>
          <div className="d-flex align-items-center mt-2">
            <img
              src={GimmeCommentsLogo}
              alt="gimme comments logo"
              style={{ height: '35px', padding: '0 5px', cursor: 'pointer' }}
              onClick={() =>
                window.open(
                  'https://gimme-comments-admin.vercel.app/',
                  '_blank'
                )
              }
            />
            <button
              className="btn btn-outline-primary ms-auto me-2"
              onClick={() => setShowMarkdownPreview(!showMarkdownPreview)}
            >
              <VscOpenPreview /> Preview
            </button>
            <button
              className="btn btn-primary"
              onClick={handleSubmit}
              disabled={userComment.comment_description === ''}
            >
              <MdSend />
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

export default CreateComment;
