import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useStore } from '../../../Context/StoreContext';
import axios from '../../../Utils/axios';
import { MdLogin, MdAccountBox } from 'react-icons/md';

const Login = () => {
  const navigate = useNavigate();
  const { setNotification } = useStore();

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleLogin = async (e) => {
    e.preventDefault();

    try {
      const res = await axios().post('/auth/login', { email, password });

      console.log(res.data);

      setNotification({
        type: 'success',
        message: 'Logged In Successfully',
      });

      setTimeout(() => {
        localStorage.setItem('gimme_comment_access_token', res.data.token);
        window.location.reload();
      }, 1000);
    } catch (err) {
      console.log(err);
      if (err.response.data.msg === 'Email is not verified') {
        setNotification({
          type: 'error',
          message: err.response.data ? err.response.data.msg : err.message,
        });
        navigate('/verify-account');
      } else {
        setNotification({
          type: 'error',
          message: err.response.data ? err.response.data.msg : err.message,
        });
      }
    }
  };

  return (
    <>
      <form onSubmit={handleLogin}>
        <label className="form-label mt-2" htmlFor="email">
          Email
        </label>
        <input
          name="email"
          id="email"
          className="form-control"
          type="text"
          value={email}
          onChange={(e) => {
            setEmail(e.target.value);
          }}
        />

        <label className="form-label mt-2" htmlFor="password">
          Password
        </label>
        <input
          name="password"
          id="password"
          className="form-control"
          type="password"
          value={password}
          onChange={(e) => {
            setPassword(e.target.value);
          }}
        />
        <button type="submit" className="btn btn-success w-100 mt-2">
          <MdLogin className="me-1" />
          Log in
        </button>
      </form>

      <div className="my-2 text-center">
        <Link to="/forget-password">Forgotten password?</Link>
      </div>
      <hr style={{ width: '90%', margin: '0 auto' }} />
      <div className="d-flex justify-content-around mt-2">
        <Link to="/sign-up">
          <button className="btn btn-primary">
            <MdAccountBox className="me-1" />
            Create new account
          </button>
        </Link>
      </div>
    </>
  );
};

export default Login;
