import React, { useEffect } from 'react';
import { Routes, Navigate, Route, Outlet } from 'react-router-dom';
import { useStore } from '../Context/StoreContext';

import Login from '../Pages/Auth/Login/Login';
import SignUp from '../Pages/Auth/SignUp/SignUp';
import ForgetPassword from '../Pages/Auth/ForgetPassword/ForgetPassword';
import VerifyAccount from '../Pages/Auth/VerifyAccount/VerifyAccount';
import CreateComment from '../Pages/Comments/CreateComment/CreateComment';
import Profile from '../Pages/Auth/Profile/Profile';
import UpdateProfile from '../Pages/Auth/Profile/UpdateProfile/UpdateProfile';
import UpdatePassword from '../Pages/Auth/Profile/UpdatePassword/UpdatePassword';
import UpdateProfileImage from '../Pages/Auth/Profile/UpdateProfileImage/UpdateProfileImage';

export default function Routing() {
  return (
    <>
      <div className="border border-1 rounded-4 px-1 py-2 bg-white">
        <Routes>
          <Route element={<UnprotectedRoute />}>
            <Route exact path="/" element={<Login />} />
            <Route exact path="/sign-up" element={<SignUp />} />
            <Route exact path="/verify-account" element={<VerifyAccount />} />
            <Route exact path="/forget-password" element={<ForgetPassword />} />
          </Route>

          <Route element={<ProtectedRoute />}>
            <Route exact path="/comment" element={<CreateComment />} />

            <Route exact path="/profile" element={<Profile />}>
              <Route
                index
                exact
                path="update-profile"
                element={<UpdateProfile />}
              />
              <Route
                exact
                path="update-password"
                element={<UpdatePassword />}
              />
              <Route
                exact
                path="update-profile-image"
                element={<UpdateProfileImage />}
              />
            </Route>
          </Route>
        </Routes>
      </div>
    </>
  );
}

const ProtectedRoute = () => {
  const access_token = localStorage.getItem('gimme_comment_access_token');
  const { getUserData } = useStore();

  useEffect(() => {
    if (!access_token) return;

    getUserData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [access_token]);

  if (access_token) {
    return (
      <>
        <Outlet />
      </>
    );
  } else {
    return <Navigate to="/" />;
  }
};

const UnprotectedRoute = () => {
  const access_token = localStorage.getItem('gimme_comment_access_token');

  if (access_token) {
    return (
      <>
        <Navigate to="/comment" />
      </>
    );
  } else {
    return <Outlet />;
  }
};
