import axios from '../../../Utils/axios';
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

import { useStore } from '../../../Context/StoreContext';
import { MdHome } from 'react-icons/md';

const ForgetPassword = () => {
  const navigate = useNavigate();

  const { setNotification } = useStore();
  const [page, setPage] = useState(1);
  const [data, setData] = useState({
    email: '',
    otp: 0,
    new_password: '',
  });

  const handleSubmit = (e) => {
    e.preventDefault();

    if (page === 1) {
      generateOTP();
    }
    if (page === 2) {
      verifyOTP();
    }
    if (page === 3) {
      updatePassword();
    }
  };

  const generateOTP = async () => {
    try {
      const res = await axios().post('/auth/forget-password/generate-otp', {
        email: data.email,
      });

      console.log(res.data);

      setNotification({
        type: 'success',
        message: res.data.msg,
      });
      setPage(2);
    } catch (err) {
      console.log(err);
      setNotification({
        type: 'error',
        message: err.response.data ? err.response.data.msg : err.message,
      });
    }
  };

  const verifyOTP = async () => {
    try {
      const res = await axios().post('/auth/forget-password/verify-otp', {
        email: data.email,
        otp: Number(data.otp),
      });

      console.log(res.data);

      setNotification({
        type: 'success',
        message: res.data.msg,
      });
      setPage(3);
    } catch (err) {
      console.log(err);
      setNotification({
        type: 'error',
        message: err.response.data ? err.response.data.msg : err.message,
      });
    }
  };

  const updatePassword = async () => {
    try {
      const res = await axios().patch('/auth/forget-password/change-password', {
        email: data.email,
        otp: Number(data.otp),
        new_password: data.new_password,
      });

      console.log(res.data);

      setNotification({
        type: 'success',
        message: res.data.msg,
      });
      navigate('/');
    } catch (err) {
      console.log(err);
      setNotification({
        type: 'error',
        message: err.response.data ? err.response.data.msg : err.message,
      });
    }
  };

  return (
    <>
      <div className="d-flex justify-content-between my-2">
        <button className="btn btn-light" onClick={() => navigate('/')}>
          <MdHome className="me-1" />
          Home
        </button>
      </div>
      <form className="d-flex flex-column" onSubmit={handleSubmit}>
        <label className="form-label mt-2" htmlFor="email">
          Enter your Email{' '}
        </label>
        <input
          name="email"
          id="email"
          autoComplete="off"
          className="form-control"
          type="email"
          value={data.email}
          disabled={!(page === 1)} // It will disabled editing
          onChange={(e) => setData({ ...data, email: e.target.value })}
        />

        {page !== 1 && (
          <>
            <label className="form-label mt-2" htmlFor="otp">
              Enter your OTP{' '}
            </label>
            <input
              name="otp"
              className="form-control"
              id="otp"
              autoComplete="off"
              type="number"
              value={data.otp}
              disabled={!(page === 2)} // It will disabled editing
              onChange={(e) =>
                setData({ ...data, otp: Number(e.target.value) })
              }
            />
          </>
        )}

        {page !== 1 && page !== 2 && (
          <>
            <label className="form-label mt-2" htmlFor="new_password">
              Enter your New Password{' '}
            </label>
            <input
              name="new_password"
              className="form-control"
              id="new_password"
              autoComplete="new-password"
              type="password"
              value={data.new_password}
              disabled={!(page === 3)} // It will disabled editing
              onChange={(e) =>
                setData({ ...data, new_password: e.target.value })
              }
            />
          </>
        )}

        <button className="btn btn-success mt-2" type="submit">
          {page === 1 && 'Get OTP'}
          {page === 2 && 'Verify OTP'}
          {page === 3 && 'Update Password'}
        </button>
      </form>
    </>
  );
};

export default ForgetPassword;
